-- ============================================================================
-- Migration: Remove Duplicate TaiKhoan Records
-- Date: 2026-10-29
-- Purpose: Xóa tài khoản trùng lặp dựa trên Email, giữ lại bản ghi có TaiKhoanID cao nhất
-- Author: Auto-generated by Qoder
-- 
-- Lưu ý QUAN TRỌNG:
-- 1. CHỈ áp dụng cho bảng TaiKhoan (tài khoản đăng nhập)
-- 2. KHÔNG xóa nhân viên hoặc khách hàng - chỉ xóa account login
-- 3. Giữ nguyên các dữ liệu liên quan (NhanVien, KhachHang)
-- 4. Đảm bảo đã backup data trước khi chạy
-- ============================================================================

-- Bước 1: Tạo temporary table chứa thông tin duplicates
DROP TEMPORARY TABLE IF EXISTS temp_duplicate_emails;
CREATE TEMPORARY TABLE temp_duplicate_emails AS
SELECT 
    LOWER(email) as email_lower,
    ARRAY_AGG(taikhoanid ORDER BY taikhoanid) as all_ids,
    MAX(taikhoanid) as keep_id
FROM taikhoan
WHERE email IS NOT NULL 
    AND email != ''
GROUP BY LOWER(email)
HAVING COUNT(*) > 1;

-- Hiển thị kết quả phân tích
SELECT 
    email_lower as duplicate_email,
    all_ids as all_taikhoan_ids,
    keep_id as keep_this_id,
    array_length(all_ids, 1) - 1 as will_be_deleted_count
FROM temp_duplicate_emails
ORDER BY email_lower;

-- Bước 2: Tạo danh sách IDs cần xóa (trừ cái cao nhất)
DROP TEMPORARY TABLE IF EXISTS temp_ids_to_delete;
CREATE TEMPORARY TABLE temp_ids_to_delete AS
SELECT 
    unnest(all_ids) as taikhoanid_to_delete
FROM temp_duplicate_emails
WHERE keep_id != unnest(all_ids);

-- Hiển thị chi tiết trước khi xóa
SELECT 
    t.email,
    t.taikhoanid,
    CASE 
        WHEN t.taikhoanid = d.keep_id THEN 'KEEP'
        ELSE 'DELETE'
    END as action
FROM taikhoan t
LEFT JOIN temp_ids_to_delete d ON t.taikhoanid = d.taikhoanid_to_delete
WHERE t.email IS NOT NULL 
    AND t.email != ''
ORDER BY LOWER(t.email), t.taikhoanid;

-- ============================================================================
-- BẮT ĐẦU XÓA DỮ LIỆU
-- ============================================================================

-- Bước A: Xóa role assignments (quan hệ vai trò)
DELETE FROM taikhoan_vaitro
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước B: Xóa notifications/thông báo gửi cho user
DELETE FROM thongbao
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước C: Xóa messages do user này gửi
DELETE FROM tinnhan
WHERE nguoiguiid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước D: Cập nhật null cho messages mà user này là người nhận
UPDATE thongbao
SET tinhanid = NULL
WHERE tinhanid IN (
    SELECT tinhanid FROM tinnhan WHERE nguoinhanid IN (
        SELECT taikhoanid_to_delete FROM temp_ids_to_delete
    )
);

-- Bước E: Xóa tin nhắn đã đọc/đã ẩn
DELETE FROM tinnhanan
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước F: Xóa device tokens (thiết bị push notification)
DELETE FROM push_device_tokens
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước G: Xóa system logs (nhật ký hệ thống)
DELETE FROM nhatkyhe_thong
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước H: Xóa lịch sử hóa đơn
DELETE FROM lichsu_thaydoi_hoadon
WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);

-- Bước I: Xóa chính tài khoản
DO $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM taikhoan
    WHERE taikhoanid IN (SELECT taikhoanid_to_delete FROM temp_ids_to_delete);
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    RAISE NOTICE '✓ Successfully deleted % duplicate TaiKhoan records', deleted_count;
END $$;

-- Bước J: Kiểm tra kết quả
DO $$
DECLARE
    total_accounts INTEGER;
    unique_emails INTEGER;
    remaining_duplicates INTEGER;
BEGIN
    SELECT COUNT(*) INTO total_accounts FROM taikhoan;
    SELECT COUNT(DISTINCT LOWER(email)) INTO unique_emails FROM taikhoan WHERE email IS NOT NULL AND email != '';
    SELECT COUNT(*) INTO remaining_duplicates FROM temp_duplicate_emails;
    
    RAISE NOTICE '═══════════════════════════════════════════════════════';
    RAISE NOTICE 'Migration Summary:';
    RAISE NOTICE '  Total accounts after cleanup: %', total_accounts;
    RAISE NOTICE '  Unique emails: %', unique_emails;
    RAISE NOTICE '  Remaining duplicates found in query: %', remaining_duplicates;
    
    IF remaining_duplicates > 0 THEN
        RAISE WARNING '⚠ Warning: Still found duplicates in analysis table!';
    ELSE
        RAISE NOTICE '✓ No duplicates remain.';
    END IF;
    
    RAISE NOTICE '═══════════════════════════════════════════════════════';
END $$;

-- Bước K: Drop temporary tables
DROP TEMPORARY TABLE IF EXISTS temp_duplicate_emails;
DROP TEMPORARY TABLE IF EXISTS temp_ids_to_delete;

-- ============================================================================
-- ADD UNIQUE CONSTRAINTS TO PREVENT FUTURE DUPLICATES
-- ============================================================================

-- Thêm constraint duy nhất cho Email
ALTER TABLE "public"."taikhoan"
ADD CONSTRAINT "taikhoan_email_unique" UNIQUE ("email");

-- Thêm constraint duy nhất cho UserAuthId (Google ID)
ALTER TABLE "public"."taikhoan"
ADD CONSTRAINT "taikhoan_userauthid_unique" UNIQUE ("userauthid")
WHERE userauthid IS NOT NULL;

